{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner st=new Scanner (System.in);
		int l=st.nextInt(); char ch; String wd="";
		int max=0,num=0;
		String s=st.next();
		int i,j=0;
		for(i=0;i<l;i++)
		{
			ch=s.charAt(i);
			if(ch=='(')
