			max=(max>wd.length())?max:wd.length();	
				wd="";
				j=1;
			}
			else if(ch==')'){
				if(wd.length()!=0)
				num++;
			j=0;
			wd="";
			}
			else if(ch=='_')
			{
				if(j==1){
				if(wd.length()!=0)
				num++;}
				else
				max=(max>wd.length())?max:wd.length();
				wd="";
			}
			else{
			wd=wd+ch;
			if(i==l-1)
			max=(max>wd.length())?max:wd.length();
			}
			}
			System.out.println(max+" "+num);
		}

